function outer() {
  const secret = 'lexical';

  function inner() {
    // 'secret' is accessible here because inner is
    // WRITTEN inside outer — lexical scope rule.
    console.log(secret); // 'lexical'
  }

  return inner;
}

const fn = outer();
fn(); // 'lexical' — outer has returned, but scope is preserved

// Assign a function to a variable
const double = n => n * 2;

// Pass a function as an argument
[1, 2, 3].map(double); // [2, 4, 6]

// Return a function from a function
function multiplier(factor) {
  return n => n * factor; // returns a new function
}
const triple = multiplier(3);
triple(5); // 15

// var hoists with undefined initializer
console.log(a);  // undefined  (not ReferenceError)
var a = 5;

// function declarations hoist fully
greet();         // 'hi'
function greet() { console.log('hi'); }

// let/const hoist into TDZ — throw if accessed early
console.log(b);  // ReferenceError: Cannot access 'b' before initialization
let b = 5;

function makeCounter() {
  let count = 0;
  return () => ++count; // closes over count
}
const c = makeCounter();
c(); // 1
c(); // 2

const arr = [1, 2, 3];
const newArr = [...arr, 4];  // [1, 2, 3, 4] — new array
// arr is unchanged: [1, 2, 3]

