interface Logger {
  log(message: string): void;
}

class ConsoleLogger implements Logger {
  log(message: string) {
    console.log(message);
  }
}

// Object destructuring with rename and default
const { name: userName, age = 18 } = { name: 'Alice' };
console.log(userName); // 'Alice'
console.log(age);      // 18 (default applied)

// Array destructuring with rest
const [first, second, ...rest] = [1, 2, 3, 4, 5];
console.log(first);  // 1
console.log(rest);   // [3, 4, 5]

// Function parameter destructuring
function greet({ name, role = 'user' }) {
  console.log(`Hello ${name}, role: ${role}`);
}
greet({ name: 'Bob' }); // Hello Bob, role: user

// || is wrong when 0 is a valid value
const volume = 0;
console.log(volume || 50);  // 50 — incorrect, overwrites intentional 0
console.log(volume ?? 50);  // 0  — correct, 0 is not nullish

// ?? only triggers on null / undefined
console.log(null ?? 'default');      // 'default'
console.log(undefined ?? 'default'); // 'default'
console.log('' ?? 'default');        // '' — empty string is not nullish

// With optional chaining
const city = user?.address?.city ?? 'Unknown';

const name = 'Alice';
const score = 42;

// Interpolation
console.log(`Hello, ${name}\! Your score is ${score * 2}.`);
// 'Hello, Alice\! Your score is 84.'

// Multi-line
const html = `
  <div class="card">
    <h2>${name}</h2>
  </div>
`;

// Tagged template (HTML sanitizer pattern)
function safe(strings, ...values) {
  return strings.reduce((acc, str, i) =>
    acc + str + (values[i] \!= null ? String(values[i]).replace(/</g,'&lt;') : ''), '');
}
const userInput = '<script>alert(1)</script>';
console.log(safe`<p>${userInput}</p>`); // <p>&lt;script>alert(1)&lt;/script></p>

function Animal(name) { this.name = name; }
Animal.prototype.speak = function() {
  return `${this.name} makes a sound.`;
};

function Dog(name) { Animal.call(this, name); }
Dog.prototype = Object.create(Animal.prototype);
Dog.prototype.constructor = Dog;
Dog.prototype.bark = function() { return 'Woof\!'; };

const d = new Dog('Rex');
console.log(d.bark());   // 'Woof\!'   — found on Dog.prototype
console.log(d.speak());  // 'Rex makes a sound.' — found on Animal.prototype
console.log(Object.getPrototypeOf(d) === Dog.prototype);      // true
console.log(Object.getPrototypeOf(Dog.prototype) === Animal.prototype); // true

function Person(name, age) {
  // 'this' refers to the newly created object
  this.name = name;
  this.age = age;
}

// Shared method on the prototype (not duplicated per instance)
Person.prototype.greet = function() {
  return `Hi, I'm ${this.name}`;
};

const alice = new Person('Alice', 30);
console.log(alice.greet()); // 'Hi, I\'m Alice'
console.log(alice instanceof Person); // true

// ES2015 class desugars to the same thing:
class PersonClass {
  constructor(name, age) { this.name = name; this.age = age; }
  greet() { return `Hi, I'm ${this.name}`; }
}

// Uncurried
const add = (a, b) => a + b;
add(2, 3);  // 5

// Curried
const addCurried = a => b => a + b;
add(2)(3);  // 5

// Partial application
const addTwo = addCurried(2);
[1, 2, 3].map(addTwo);  // [3, 4, 5]

// O(n²) — nested loops over same array
function hasDuplicateNaive(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++)
      if (arr[i] === arr[j]) return true;
  return false;
}

// O(n) — single pass with a Set
function hasDuplicate(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}

let value = 'outer';

function process() {
  let value = 'inner'; // shadows outer 'value'
  console.log(value);  // 'inner'
}

process();
console.log(value); // 'outer' — unchanged, was never touched

// Shadowing can mask bugs:
let count = 10;
for (let i = 0; i < 3; i++) {
  let count = i; // shadows outer count — probably unintentional
  console.log(count); // 0, 1, 2
}
console.log(count); // 10 — outer count untouched

